{{ config(materialized = 'ephemeral') }}

-- ZOOMINFO_DEV -> company_hierarchy: generated by dbt-onboard-source from the approved STTM.
-- SOURCE_UNIQUE_ID: STTM business keys.

with sp_company_hierarchy as (
    select
        upper(trim(o.ZOOMINFO_ID)) as source_unique_id,
        nullif(trim(o.COMPANY_NAME), '') as company_name
    from {{ source('company_hierarchy_zoominfo_dev_source', 'silver_zoominfo_company') }} as o
    where nullif(upper(trim(o.ZOOMINFO_ID)), '') is not null
    qualify row_number() over (partition by upper(trim(o.ZOOMINFO_ID)) order by source_unique_id) = 1
),

ref_source_system as (
    {{ m_get_source_system_skey_company('ZOOMINFO_DEV') }}
),

base as (
    select
        o.source_unique_id,
        r.gdp_source_system_skey as ref_gdp_source_system_skey,
        hub.company_core_skey as company_core_skey,
        o.company_name as company_name,
        null as ref_company_type_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_COMPANY_TYPE_SKEY */,
        null as domestic_parent_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for DOMESTIC_PARENT_SKEY */,
        null as global_parent_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for GLOBAL_PARENT_SKEY */,
        null as hierarchy_level,
        null as hierarchy_path,
        null as valid_from,
        null as valid_to,
        null as ref_hierarchy_type_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for REF_HIERARCHY_TYPE_SKEY */,
        true as gdp_is_active,
        current_timestamp()::timestamp_ntz as gdp_inserted_ts,
        current_user() as gdp_inserted_by,
        current_timestamp()::timestamp_ntz as gdp_updated_ts,
        current_user() as gdp_updated_by,
        null as immediate_parent_skey /* TODO: FK lookup pending: add ref CTE + LEFT JOIN on upper(trim(...)) for IMMEDIATE_PARENT_SKEY */
    from sp_company_hierarchy as o
    cross join ref_source_system as r
    left join (
        select source_unique_id, company_core_skey
        from {{ ref('company_core') }}
        where gdp_is_active
        qualify row_number() over (partition by source_unique_id order by gdp_inserted_ts desc) = 1
    ) as hub
        on hub.source_unique_id = o.source_unique_id
)

select
    {{ this.schema }}.seq_company_hierarchy_skey.nextval as company_hierarchy_skey,
    source_unique_id,
    ref_gdp_source_system_skey,
    company_core_skey,
    company_name,
    ref_company_type_skey,
    domestic_parent_skey,
    global_parent_skey,
    hierarchy_level,
    hierarchy_path,
    valid_from,
    valid_to,
    ref_hierarchy_type_skey,
    {{ m_company_hierarchy_hkey() }} as company_hierarchy_hkey,
    gdp_is_active,
    gdp_inserted_ts,
    gdp_inserted_by,
    gdp_updated_ts,
    gdp_updated_by,
    immediate_parent_skey
from base
